@startuml

class Kinepolis {
  + Name : string
}

class Cinema {
  + Town : string
}

class Theatre {
  + Name : string
  + SeatCount : int
}

class Movie {
  + Title : string
}

class MovieCopy {
  + CopyId : string
}

class Show {
  + StartTime : datetime
  + IsPublished : boolean
}

class Reservation {
  + ReservationTime : datetime
  + IsCancelled : boolean
}

class CreditCard {
  + CardNumber : string
}

class Ticket {
  + SeatNumber : string
  + IsAnonymous : boolean
}

class Offer {
  + ExpiryTime : datetime
}

Kinepolis "1" -- "*" Cinema
Cinema "1" *-- "*" Theatre
Cinema "1" -- "*" MovieCopy
Movie "1" -- "*" MovieCopy
Theatre "1" -- "*" Show
MovieCopy "1" -- "*" Show
Show "1" -- "*" Reservation
Show "1" -- "*" Ticket
Show "1" -- "0..1" Offer
Reservation "0..*" -- "1" CreditCard
Reservation "0..*" -- "1" Customer
Ticket "0..*" -- "1" Show
Ticket "0..*" -- "1" Customer

class Customer {
  + Name : string
}

@enduml

